function candidates(result,rows){
 const raw=typeof result==="string"?result:JSON.stringify(result);
 const blocks=raw.split(/\n-{20,}\n/);
 return rows.map(row=>{
  const [year,ms]=row.economic_period.split("M"),month=Number(ms);
  const c=blocks.map((b,j)=>{
   const first=b.trimStart().match(/^(.+?)\s*\((https?:\/\/[^)\s]+)\)/);
   if(!first)return null;const url=first[2];
   const primary=/^https?:\/\/www\.stats\.gov\.cn\/(?:sj\/zxfb|tjsj\/zxfb|xxgk\/sjfb\/zxfb2020)\//.test(url)&&!/\.(?:pdf|xls|xlsx)$/i.test(url);
   if(!primary)return null;
   const direct=(first[1].replace(/\s+/g,"").match(/(\d{4})年0?(\d{1,2})月(?:份)?(?:全国)?工业生产者(?:出厂)?价格/));
   const lead=direct??(/^国家统计局信息公开/.test(first[1])?b.replace(/\s+/g,"").match(/(\d{4})年0?(\d{1,2})月(?:份)?[，,]?(?:全国)?工业生产者(?:出厂)?价格/):null);
   return lead&&lead[1]===year&&Number(lead[2])===month?{result_order:j,title:first[1],url,context:b}:null;
  }).filter(Boolean);
  return {economic_period:row.economic_period,query:row.fixed_locator_query,candidates:c,selected:c[0]??null,selection_status:c.length?"FIRST_RETURNED_ORIGINAL_CANDIDATE":"UNKNOWN_NO_ORIGINAL_CANDIDATE"};
 });
}
